            if (CheckLandTransferProposal(world, transferProposalPlan).Refusal is { } refusal) { world.RefuseChoice(transferProposalPlan, refusal); return; }
        }
        else if (HouseholdLandFilingChoice.Decode(selectedId) is { } filingChoice)
        {
