internal sealed partial class TownSystem
{
    internal static readonly string[] NonLandFindingChoices = ["unsupported", "explanation", "warning", "censure"];
    internal void AddChildNonLandCandidates(ITownWorld world, List<CognitionCandidate> candidates, string actor)
    {
        if (!world.IsChild(actor) || WorldRuntime.CivicSharedRules.NeedsUrgentFood(world.Agents[actor]) || world.NeedsUrgentWarmth(world.Agents[actor])) return;
        var first = candidates.Count;
        foreach (var town in world.Towns.Where(town => town.FoundingState == "founded" && town.Council is not null))
            AddTownNonLandCandidates(world, candidates, actor, town);
        AttachCivicVisitPlans(world, candidates, actor, first);
    }

    internal void AddTownNonLandCandidates(ITownWorld world, List<CognitionCandidate> candidates, string actor, TownRuntimeState town)
    {
        if (town.Council is not { } council || !world.Agents.TryGetValue(actor, out var actorState) || LifeStageRules.IsInfant(world.Society.GetAgent(actor).AgeBand)) return;
        var adult = LandHearingAdult(world, actor);
        var atBoard = NearCivicBoard(world, actor, town);
        var history = CivicHistory(town);
        if (!atBoard && MayVisitNonLandCase(world, actor, town) && !candidates.Any(candidate => candidate.Id == CivicAction(world, town.Id, "visit")))
        {
            var choice = new CivicVisitChoice(town.Id);
            if (PlanCivicVisit(world, actor, choice) is { } plan && CheckCivicVisit(world, plan).Allowed)
                candidates.Add(new(choice.Encode(), "Visit the public notice place for a reported act you actually know about. Visiting grants no membership or private access.", 175)
                { ActionPlan = plan });
        }
        var offeredReports = 0;
        if (adult && atBoard)
            foreach (var report in NonLandKnownReports(world, town, actor).Where(report => !town.NonLandHearings.Cases.Any(item =>
                         item.Key == TownNonLandRules.CaseKey(town.Id, report.Allegation) &&
                         (item.Status != "pending" || item.Filings.Any(filing => filing.AgentId == actor &&
                             (filing.Kind == "affected" || actor == item.Allegation.SubjectId))))))
            {
                var beforeReport = candidates.Count;
                var label = "Report known conduct as an allegation: " + NonLandKnownAllegationText(world, town, report.Allegation) +
                    ". Supply civic_nonviolent.statement explaining the alleged breach; the engine does not decide guilt. Source: " + report.Evidence.Acquisition + ".";
                if (!town.NonLandHearings.Cases.Any(item => item.Key == TownNonLandRules.CaseKey(town.Id, report.Allegation) && item.Filings.Any(filing => filing.AgentId == actor)))
                    OfferNonLandFiling(world, candidates, actor, town, report, "law_case_file", label, 185);
                if (actor != report.Allegation.SubjectId)
                    OfferNonLandFiling(world, candidates, actor, town, report, "law_case_file_affected",
                        "Report this known act as personally affecting you, explaining your claimed harm in civic_nonviolent.statement. Your claimed stake grants a response opportunity, not proof that the allegation or harm is true. " + label, 185);
                if (town.Government is { } government && TownAdults(world, town).Contains(actor, StringComparer.Ordinal))
                {
                    if (government.Arrangement.Ordinary == TownArrangementRules.Mayor && government.Offices.Any(office =>
                            office.Mandates == "ordinary" && office.HolderId == actor && office.TermEndTick > world.WorldTick))
                        OfferNonLandFiling(world, candidates, actor, town, report, "law_case_file_town", "File this known allegation under your current ordinary Town office. " + label, 186);
                    else if (government.Arrangement.Ordinary is TownArrangementRules.Council or TownArrangementRules.ElectedCouncil or TownArrangementRules.AllAdultCouncil &&
                        council.Members.Contains(actor, StringComparer.Ordinal))
                        OfferNonLandFiling(world, candidates, actor, town, report, "law_case_propose_town", "Ask the Council to authorize this known Town allegation; approval is required. " + label, 186);
                }
                if (candidates.Count > beforeReport && ++offeredReports == 6) break;
            }
        foreach (var item in town.NonLandHearings.Cases)
        {
            var revision = NonLandRevision(item);
            var token = NonLandActionToken(item);
            var parties = NonLandParties(world, town, item);
            var isParty = parties.Any(party => party.SubjectId == actor || party.RespondingAdultId == actor);
            if (atBoard && NonLandMayInspect(world, town, item, actor) && (!NonLandReadCurrent(world, item, actor) ||
                item.ReopenRequests.Any(request => !item.Reads.Any(read => read.AgentId == actor && read.ReopenRequestIds.Contains(request.Id, StringComparer.Ordinal)))))
                OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_inspect", "",
                    "Read this public case, its alleged act, historical law and sourced evidence. It remains an allegation until a reasoned finding; reading grants no private access.", 177);
            if (!NonLandKnows(world, town, item, actor)) continue;
            if (NonLandMayInspect(world, town, item, actor))
            {
                OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_statement", "",
                    "Submit your own statement via civic_nonviolent.statement. A child may speak with caregiver support; testimony is not a verified fact or another person's consent.", 182);
                if (NonLandKnownEvidence(world, town, item, actor).Any(evidence => !item.Evidence.Any(old => old.SourceRecordId == evidence.SourceRecordId &&
                        old.SourceVersion == evidence.SourceVersion && old.SubmittedByAgentId == actor)))
                    OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_evidence", "", "Submit only evidence you actually observed or lawfully learned. Private information stays private.", 181);
            }
            if (adult && council.Members.Contains(actor, StringComparer.Ordinal) && town.Government?.Arrangement.NonLand != TownArrangementRules.Mayor)
                OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_advise", "", "Offer Council mediation or advice via civic_nonviolent.statement while the formal non-land mandate is absent. Advice is a sourced statement, not a finding or enforceable consequence.", 183);
            foreach (var party in parties.Where(party => item.Status == "pending" && party.RespondingAdultId == actor &&
                         !item.Responses.Any(response => response.Revision == revision.Number && response.PartyId == party.Id)))
            {
                OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_answer", party.Id,
                    "Answer this allegation for " + world.Society.GetAgent(party.SubjectId).Name +
                    (party.SubjectId == actor ? "." : " with your actual caregiver support.") + " Supply civic_nonviolent.statement. This promises no goods or work." + NonLandEvidenceChoices(world, town, item, actor), 165);
                OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_waive", party.Id, "Explicitly waive only this person's current response opportunity; this admits nothing and supplies no restorative consent.", 166);
            }
            if (adult && TownAdults(world, town).Contains(actor, StringComparer.Ordinal) && (item.Status == "pending" || item.ReopenRequests.Any(request => request.Status == "pending")))
            {
                var willing = item.JudgeConsents.Any(consent => consent.AgentId == actor && consent.WithdrawnTick is null);
                if (!willing && !NonLandConflict(world, town, item, actor)) OfferNonLandJudge(world, candidates, actor, town, item, NonLandJudgeKind.Register, "", "Personally agree to stand as an independent judge of this case only, subject to actual resident election.", 180);
                if (willing) OfferNonLandJudge(world, candidates, actor, town, item, NonLandJudgeKind.Withdraw, "", "Withdraw your willingness to adjudicate this case; its records remain.", 185);
                if (item.Judge is { Kind: "case_elected" } held && held.AgentId == actor)
                    OfferNonLandJudge(world, candidates, actor, town, item, NonLandJudgeKind.Resign, "", "Resign your authority over this case only.", 185);
            }
            if (item.Contest is { Stage: "voting" } contest && contest.Voters.Contains(actor, StringComparer.Ordinal) && history.Knows(actor, TownCaseJudgeRules.RoundToken(contest)))
                foreach (var candidate in contest.Candidates)
                    OfferNonLandJudge(world, candidates, actor, town, item, NonLandJudgeKind.Vote, candidate,
                        "Vote for " + world.Society.GetAgent(candidate).Name + " as independent judge of this case only.", 167);
            if (item.Judge is { } judge && judge.AgentId == actor && NonLandJudgeValid(world, town, item, judge) && NonLandReadCurrent(world, item, actor))
            {
                if (item.Status == "pending" && TownNonLandRules.CanCloseResponses(item, parties, world.WorldTick))
                    foreach (var outcome in NonLandFindingChoices.Where(outcome => outcome != "censure" ||
                                 HasPriorLawNotice(town, item.Allegation, item.Allegation.SubjectId)))
                        OfferNonLandAdjudication(world, candidates, actor, town, item, "law_case_find", outcome,
                            "Record " + outcome + ". An adverse finding requires more-likely-than-not evidence, reasons and uncertainty in civic_nonviolent; rumor or silence alone is insufficient. A first incident without credible prior law notice favors explanation or warning. No property or membership changes." + NonLandEvidenceChoices(world, town, item, actor), 165);
                foreach (var request in item.ReopenRequests.Where(request => request.Status == "pending" && item.Reads.Any(read => read.AgentId == actor &&
                             read.Revision == revision.Number && read.ReopenRequestIds.Contains(request.Id, StringComparer.Ordinal))))
                {
                    if (request.Kind == "material_evidence" ? TownNonLandRules.MaterialNewEvidence(item, request) : TownNonLandRules.DemonstratedProceduralError(item, request))
                        OfferNonLandAdjudication(world, candidates, actor, town, item, "law_case_assess_reopen", request.Id + ":accept", "Reopen on established material evidence or procedure error, with reasons in civic_nonviolent.statement. Prior findings and physical effects remain recorded.", 165);
                    OfferNonLandAdjudication(world, candidates, actor, town, item, "law_case_assess_reopen", request.Id + ":reject", "Explain why these reopening grounds are not established; retain the request and prior result.", 166);
                }
            }
            if (item.Status == "settled" && isParty && NonLandReadCurrent(world, item, actor))
                foreach (var grounds in new[] { "material_evidence", "procedural_error" })
                    OfferNonLandAdjudication(world, candidates, actor, town, item, "law_case_reopen", grounds, "Request reopening for " + grounds.Replace('_', ' ') + ". Supply actual evidence_ids and grounds; a claim alone changes no finding." + NonLandEvidenceChoices(world, town, item, actor), 184);
            if (adult && item.Findings.Count > 0 && item.Findings[^1] is { Result: "supported" } finding && NonLandReadCurrent(world, item, actor) &&
                (isParty || finding.Judge.AgentId == actor && NonLandJudgeValid(world, town, item, finding.Judge)))
                OfferNonLandAgreement(world, candidates, actor, town, "remedy_offer", token, finding.Id,
                    "Offer feasible named goods, repair or Town resource delivery in civic_nonviolent.terms, with reasons and optional completion_ticks (default three days after consent). Each contributing adult must personally agree. No stock is reserved and no work forced." + NonLandRemedyReferences(world, town, actor), 183);
            foreach (var recipient in world.Agents.Values.Where(person => person.AgentId != actor && world.IsWithinInteractionRange(person.Position, actorState.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange)))
                if (NonLandReadCurrent(world, item, actor) && NonLandMayInspect(world, town, item, recipient.AgentId) && !NonLandReadCurrent(world, item, recipient.AgentId))
                    OfferNonLandEvidence(world, candidates, actor, town, item, "law_case_relay", recipient.AgentId, "Relay the case material you actually read to " + world.Society.GetAgent(recipient.AgentId).Name + " nearby.", 181);
        }
        foreach (var agreement in town.NonLandHearings.Agreements.Where(agreement => adult && agreement.Status != "completed" &&
                     !TownRemedyRules.IsSuperseded(town.NonLandHearings, agreement.Id) && agreement.Terms.Any(term => term.ContributorId == actor)))
        {
            var original = town.NonLandHearings.Offers.Single(offer => offer.Id == agreement.OfferId);
            var file = town.NonLandHearings.Cases.Single(item => item.Id == original.CaseId);
            if (NonLandReadCurrent(world, file, actor) && !town.NonLandHearings.Offers.Any(offer => offer.CaseId == file.Id && offer.Status == "pending"))
                OfferNonLandAgreement(world, candidates, actor, town, "remedy_renegotiate", agreement.Id, agreement.TermsHash,
                    "Request a feasible change to your unfinished voluntary agreement via civic_nonviolent.terms. Prior work remains recorded; replacement terms require fresh consent. Inability is no new offense." + NonLandRemedyReferences(world, town, actor), 183);
        }
        foreach (var offer in town.NonLandHearings.Offers.Where(offer => offer.Status == "pending" && world.WorldTick < offer.ResponseDeadlineTick &&
                     offer.Terms.Any(term => term.ContributorId == actor)))
        {
            if (atBoard && !history.Known(actor).Contains(offer.NoticeId))
                OfferNonLandAgreement(world, candidates, actor, town, "remedy_read", NonLandOfferToken(offer), "", "Read the actual voluntary offer: " + NonLandTermsText(offer.Terms) + ". " + NonLandOfferTiming(world, offer) + " Publication alone is not your awareness or consent.", 177);
            if (!adult || !history.Known(actor).Contains(offer.NoticeId) || offer.Responses.Any(response => response.AgentId == actor && response.Kind == "accept")) continue;
            if (NonLandRemedyCapacityFeasible(world, offer.Terms) &&
                NonLandRemedyDurationFeasible(world, town, offer.Terms.Where(term => term.ContributorId == actor).ToArray(), offer.CompletionTicks))
                OfferNonLandAgreement(world, candidates, actor, town, "remedy_accept", NonLandOfferToken(offer), "", "Personally accept your exact contribution: " + NonLandTermsText(offer.Terms.Where(term => term.ContributorId == actor)) + ". " + NonLandOfferTiming(world, offer) + " This does not start work or reserve goods.", 165);
            OfferNonLandAgreement(world, candidates, actor, town, "remedy_decline", NonLandOfferToken(offer), "", "Decline this voluntary offer. Declining creates no offense or automatic penalty.", 166);
            OfferNonLandAgreement(world, candidates, actor, town, "remedy_counter", NonLandOfferToken(offer), "", "Counter with feasible named terms in civic_nonviolent.terms; everyone must read and consent to the new offer." + NonLandRemedyReferences(world, town, actor), 183);
        }
    }

    internal static string NonLandTermsText(IEnumerable<TownRemedyTerm> terms) => string.Join("; ", terms.Select(term =>
        term.Quantity + " " + (term.ItemKind ?? term.Kind).Replace('_', ' ') + " by " + CivicAgentToken(term.ContributorId) +
        (term.BeneficiaryId is { } beneficiary ? " for " + CivicAgentToken(beneficiary) : "") + (term.TargetId is { } target ? " at " + CivicAgentToken(target) : "")));
    internal static string NonLandDaysText(ITownWorld world, long ticks) =>
        ((decimal)ticks / CivicDay(world)).ToString("0.################", System.Globalization.CultureInfo.InvariantCulture) +
        (ticks == CivicDay(world) ? " world day" : " world days");
    internal static string NonLandOfferTiming(ITownWorld world, TownRemedyOffer offer) =>
        "Complete within " + NonLandDaysText(world, offer.CompletionTicks) + " after everyone accepts. Answer within " +
        NonLandDaysText(world, offer.ResponseDeadlineTick - offer.PublishedTick) + " of publication.";
    internal string NonLandRemedyReferences(ITownWorld world, TownRuntimeState town, string actor)
    {
        var people = world.Agents.Values.Where(person => person.AgentId == actor || town.ResidentIds.Contains(person.AgentId) || world.IsWithinInteractionRange(person.Position, world.Agents[actor].Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange)).ToArray();
        var lots = world.Society.Inventory.Lots.Where(lot => lot.OwnerId == actor || lot.OwnerId == world.HouseholdFor(actor) || world.Agents.TryGetValue(lot.OwnerId, out var holder) && ToolProgressionRules.IsTopLevelCarriedLot(lot, lot.OwnerId) && world.IsWithinInteractionRange(holder.Position, world.Agents[actor].Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange) &&
            CanObserveNonLandAct(world, actor, lot.OwnerId, holder.Position));
        var warehouses = world.WorldSimulation.Buildings.Where(building => building.TownId == town.Id &&
            (TownForResident(world, actor) == town.Id || world.IsWithinInteractionRange(building.Position, world.Agents[actor].Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange)));
        return " Use these references in terms. People: " + string.Join("; ", people.Select(person => world.Society.GetAgent(person.AgentId).Name + " (" + CivicAgentToken(person.AgentId) + ")")) +
            ". Town: " + town.Name + " (" + CivicAgentToken(town.Id) + "). Known goods: " + string.Join("; ", lots.Select(lot =>
                lot.ItemKind.Replace('_', ' ') + " (" + CivicAgentToken(lot.Id) + ") held by " + CivicAgentToken(lot.OwnerId))) +
            ". Known Town buildings: " + string.Join("; ", warehouses.Select(building => CivicAgentToken(building.InstanceId))) + ".";
    }
}

using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using ClankerWorld.Simulation.Cognition;
using ClankerWorld.Simulation.Society;

namespace ClankerWorld.Simulation.World;

internal sealed partial class TownSystem
{
    internal static string NonLandToken(string text) => DerivedId.Hash(text);
    internal static string NonLandReportToken(TownViolationAllegation report) => NonLandToken(report.IncidentId + "|" + report.LawId + "|" + report.LawVersion.ToString(CultureInfo.InvariantCulture));
    internal static string NonLandOfferToken(TownRemedyOffer offer) => DerivedId.Create(offer.Id + ":" + offer.Revision.ToString(CultureInfo.InvariantCulture) + ":" + offer.TermsHash);
    internal static TownCaseRevision NonLandRevision(TownNonLandCase item) => item.Revisions[^1];
    internal static string NonLandCaseToken(TownNonLandCase item) => DerivedId.Create(item.Id + ":" + NonLandRevision(item).Number.ToString(CultureInfo.InvariantCulture));
    internal static string NonLandActionToken(TownNonLandCase item) => DerivedId.Create(item.Id + ":" +
        NonLandRevision(item).Number.ToString(CultureInfo.InvariantCulture) + ":" +
        TownHearingProcedure.Digest(new { item.Evidence, item.Responses, item.Findings, item.Judge, item.ReopenRequests }));
    internal static TownCaseParty[] NonLandParties(ITownWorld world, TownRuntimeState town, TownNonLandCase item) =>
        TownNonLandPartyRules.CurrentParties(town, item, world.Society, world.WorldTick);
    internal static bool NonLandMayInspect(ITownWorld world, TownRuntimeState town, TownNonLandCase item, string actor) => world.Agents.ContainsKey(actor) && !LifeStageRules.IsInfant(world.Society.GetAgent(actor).AgeBand) &&
        (TownAdults(world, town).Contains(actor, StringComparer.Ordinal) || item.Judge?.AgentId == actor ||
            item.Filings.Any(filing => filing.AgentId == actor) ||
            town.NonLandHearings.Offers.Any(offer => offer.CaseId == item.Id && offer.Terms.Any(term => term.ContributorId == actor)) || NonLandParties(world, town, item).Any(party =>
                party.SubjectId == actor || party.RespondingAdultId == actor));
    internal static bool NonLandReadCurrent(ITownWorld world, TownNonLandCase item, string actor) => TownNonLandRules.ReadCurrent(item, actor, world.WorldTick);
    internal static bool NonLandKnows(ITownWorld world, TownRuntimeState town, TownNonLandCase item, string actor) =>
        town.Council!.Knowledge.Any(receipt => receipt.AgentId == actor && receipt.NoticeId == NonLandRevision(item).NoticeId && receipt.LearnedTick <= world.WorldTick);
    internal static bool NonLandConflict(ITownWorld world, TownRuntimeState town, TownNonLandCase item, string actor) =>
        item.Filings.Any(filing => filing.AgentId == actor) || item.DirectStakeIds.Contains(actor, StringComparer.Ordinal) ||
        NonLandParties(world, town, item).Any(party => party.SubjectId == actor || party.RespondingAdultId == actor ||
            party.HouseholdId is { } household && household == world.HouseholdFor(actor));
    internal static bool NonLandJudgeValid(ITownWorld world, TownRuntimeState town, TownNonLandCase item, TownCaseJudge judge)
    {
        if (!TownAdults(world, town).Contains(judge.AgentId, StringComparer.Ordinal) || NonLandConflict(world, town, item, judge.AgentId) ||
            town.Government is not { } government || government.Arrangement.NonLand != TownArrangementRules.Mayor) return false;
        if (judge.Kind == "case_elected") return item.JudgeConsents.Any(consent => consent.AgentId == judge.AgentId && consent.WithdrawnTick is null) &&
            item.ContestHistory.Any(contest => contest.Id == judge.AuthorityId && contest.Stage == "completed" && contest.WinnerId == judge.AgentId);
        return judge.Kind == "non_land_mayor" && TownGovernmentRules.CurrentNonLandAuthority(government, world.WorldTick) is { } authority &&
            authority.HolderId == judge.AgentId && authority.AuthorityId == judge.AuthorityId;
    }

    internal static bool TownNonLandElectionBusy(TownRuntimeState town) => town.NonLandHearings.Cases.Any(item => item.Contest is { Stage: "voting" });
    internal static bool MayVisitNonLandCase(ITownWorld world, string actor, TownRuntimeState town) => world.Agents.ContainsKey(actor) && CanWalkToCivicBoard(world, actor, town) && (town.NonLandHearings.Cases.Any(item => NonLandMayInspect(world, town, item, actor) && NonLandKnows(world, town, item, actor)) ||
            NonLandKnownReports(world, town, actor).Length > 0);
    internal static (TownCouncilState Council, TownNonLandHearingState NonLandHearings) AdvanceTownNonLand(ITownWorld world, TownRuntimeState town,
        TownCouncilState council, TownGovernmentState government)
    {
        var state = TownRemedyRules.Advance(town.NonLandHearings, world.WorldTick);
        foreach (var proposal in council.Proposals.Where(proposal => proposal.Kind == "law_case" && proposal.Status == "passed" && proposal.NonLandRequest is not null).ToArray())
        {
            if (state.Cases.Any(item => item.Filings.Any(filing => filing.AuthorityId == proposal.Id)) ||
                government.Arrangement.Ordinary is not (TownArrangementRules.Council or TownArrangementRules.ElectedCouncil or TownArrangementRules.AllAdultCouncil) ||
                !council.Members.Contains(proposal.AuthorId, StringComparer.Ordinal) || !TownAdults(world, town).Contains(proposal.AuthorId, StringComparer.Ordinal)) continue;
            var request = proposal.NonLandRequest!;
            if (state.Cases.Any(item => item.Key == TownNonLandRules.CaseKey(town.Id, request.Allegation) && item.Status != "pending")) continue;
            var report = NonLandKnownReports(world, town with { Council = council, NonLandHearings = state }, proposal.AuthorId)
                .FirstOrDefault(report => NonLandReportToken(report.Allegation) == NonLandReportToken(request.Allegation));
            if (report.Allegation is null) continue;
            (council, state) = OpenNonLandCase(world, town, council, state, request.Allegation,
                new(proposal.AuthorId, "town", world.WorldTick, request.Statement, request.Allegation.SourceEvidenceIds, proposal.Id), report.Evidence);
        }
        foreach (var item in state.Cases.Where(item => item.Status == "pending").ToArray())
        {
            var before = NonLandRevision(item).Number;
            state = TownNonLandRules.ReviseParties(state, item.Id, NonLandParties(world, town, item), world.WorldTick, CivicDay(world), TownCouncilRules.NextNoticeId(council));
            var revised = state.Cases.Single(current => current.Id == item.Id);
            if (NonLandRevision(revised).Number != before) council = PostNonLandNotice(council, revised);
        }
        state = state with
        {
            Cases = state.Cases.Select(item => item with
            { DirectStakeIds = item.Filings.Select(filing => filing.AgentId).Concat(NonLandParties(world, town, item).Select(party => party.SubjectId)).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray() }).ToArray()
        };
        var parties = state.Cases.ToDictionary(item => item.Id, item => (IReadOnlyList<TownCaseParty>)NonLandParties(world, town, item), StringComparer.Ordinal);
        (state, council) = TownCaseJudgeRules.Advance(state, council, government, TownAdults(world, town), LandHearingHouseholds(world), world.WorldTick, CivicDay(world), TownLandHearingElectionBusy(town) || government.Contest is { Stage: "voting" or "ready" } || council.Election is { Stage: "ready" }, parties);
        return (council, state);
    }

    internal static TownCouncilState PostNonLandNotice(TownCouncilState council, TownNonLandCase item) =>
        TownCouncilRules.PostNotice(council, "law_case", NonLandCaseToken(item),
            "A reported act is alleged to breach a Town law. The named people may answer with caregiver support where needed. No guilt, payment or work is presumed.", NonLandRevision(item).PublishedTick);
    internal static void NonLandEvent(ITownWorld world, string kind, TownRuntimeState town, string subject, string actor) => world.AppendEvent(WorldEvents.LawCase(kind, actor, town.Id, subject), CivicBoard(world, town));
    internal static string NonLandText(string? text) => CognitionDecisionResponse.NormalizeIdentityText(text) ??
        throw new InvalidOperationException("A legal submission needs a clear personal statement.");

    internal static string NonLandKnownAllegationText(ITownWorld world, TownRuntimeState town, TownViolationAllegation allegation)
    {
        var version = town.Government!.Laws.Single(law => law.Id == allegation.LawId).Versions.Single(version => version.Version == allegation.LawVersion);
        return BoundedText.Excerpt(world.Society.GetAgent(allegation.SubjectId).Name, 80) + " allegedly " +
            allegation.ConductKind.Replace('_', ' ') + " at (" + allegation.Position.X + "," + allegation.Position.Y + ") at world tick " +
            allegation.ConductTick.ToString(CultureInfo.InvariantCulture) + ". Known source: " + BoundedText.Excerpt(allegation.Statement, 256) +
            ". Applicable law version " + allegation.LawVersion.ToString(CultureInfo.InvariantCulture) + ": " +
BoundedText.Excerpt(TownLawRules.Text(version.Subject, version.Rule), 512);
    }

    internal static string NonLandEvidenceChoices(ITownWorld world, TownRuntimeState town, TownNonLandCase item, string actor)
    {
        var reads = item.Reads.Where(read => read.AgentId == actor && read.Revision == NonLandRevision(item).Number && read.ReadTick <= world.WorldTick).ToArray();
        var known = reads.SelectMany(read => read.EvidenceIds).ToHashSet(StringComparer.Ordinal);
        var responses = reads.SelectMany(read => read.ResponseIds).ToHashSet(StringComparer.Ordinal);
        var findings = reads.SelectMany(read => read.FindingIds).ToHashSet(StringComparer.Ordinal);
        return (reads.Length == 0 ? "" : " Inspected allegation: " + NonLandKnownAllegationText(world, town, item.Allegation) + ".") +
            " Inspected evidence: " + string.Join("; ", item.Evidence.Where(evidence => known.Contains(evidence.Id)).TakeLast(8)
            .Select(evidence => CivicAgentToken(evidence.Id) + " (" + evidence.Kind + ", " + evidence.Acquisition + "): " + BoundedText.Excerpt(evidence.Text, 256))) +
            ". Inspected responses: " + string.Join("; ", item.Responses.Where(response => responses.Contains(TownNonLandRules.ResponseToken(response))).TakeLast(8)
                .Select(response => BoundedText.Excerpt(world.Society.GetAgent(response.AgentId).Name, 80) + " " + response.Kind + ": " + BoundedText.Excerpt(response.Text, 256))) +
            ". Inspected prior findings: " + string.Join("; ", item.Findings.Where(finding => findings.Contains(finding.Id)).TakeLast(4)
                .Select(finding => finding.Id + " " + finding.Result + "/" + finding.Consequence + ": " + BoundedText.Excerpt(finding.Reasons, 256) +
                    "; uncertainty: " + BoundedText.Excerpt(finding.Uncertainty, 160))) + ".";
    }
}

using System.Security.Cryptography;
using System.Text.Json;
using ClankerWorld.Simulation.Cognition;
using ClankerWorld.Simulation.Content;
using ClankerWorld.Simulation.Kernel;
using ClankerWorld.Simulation.Society;

namespace ClankerWorld.Simulation.World;

internal sealed partial class TownSystem
{
    internal const string NonLandRemedyPrefix = "nonviolent_remedy:";
    internal const string NonLandRelayPrefix = "nonviolent_relay:";
    internal const int UnfiledConductLimit = 256;
    internal static string NonLandDigest<T>(T value) =>
        DerivedId.Hash(JsonSerializer.Serialize(value));
    internal static string ConductLawDigest(TownLawVersion version) => NonLandDigest(new
    {
        version.Version,
        version.Subject,
        version.Rule,
        version.Scope,
        version.SiteTiles,
        version.ProposalId,
        version.AdoptedTick,
    });
    internal void RecordNonLandConduct(ITownWorld world, string actor, string kind, GridPoint position, string? targetId,
        string? itemKind, int quantity, string nativeActId)
    {
        if (!world.Agents.ContainsKey(actor)) return;
        nativeActId = DerivedId.Create(nativeActId);
        var actorTownId = TownForResident(world, actor);
        foreach (var town in world.Towns.ToArray())
        {
            if (town.Government is null) continue;
            var titles = world.TownLandTitles.Where(title => title.RecordedTick <= world.WorldTick).ToArray();
            var applicable = TownLawRules.Applicable(town.Government, town.Id, titles,
                actorTownId == town.Id, position, world.WorldTick);
            if (applicable.Count == 0 || town.NonLandHearings.ConductRecords.Any(record => record.Id == nativeActId)) continue;
            var laws = applicable.Select(pair => new TownConductLawSnapshot(pair.Law.Id, pair.Version.Version,
                ConductLawDigest(pair.Version), pair.Version.Scope,
                titles.Where(title => title.TownId == town.Id && title.Tiles.Contains(position))
                    .Select(title => title.Id).Order(StringComparer.Ordinal).ToArray(),
                (town.Council?.Knowledge ?? []).Where(receipt => receipt.AgentId == actor && receipt.LearnedTick <= world.WorldTick &&
                    town.Council!.Notices.Any(notice => notice.Id == receipt.NoticeId && notice.Kind == "law" &&
                        notice.SubjectId == pair.Law.Id && notice.PostedTick >= pair.Version.AdoptedTick && notice.PostedTick <= world.WorldTick))
                    .Select(receipt => receipt.NoticeId).Order(StringComparer.Ordinal).ToArray())).ToArray();
            var record = new TownConductRecord(nativeActId, actor, kind, position, world.WorldTick, actorTownId,
                targetId, itemKind, quantity, laws, "");
            record = record with { Version = NonLandDigest(record) };
            var observations = world.Agents.Values.Where(person => person.AgentId == actor ||
                    CanObserveNonLandAct(world, person.AgentId, actor, position))
                .OrderBy(person => person.AgentId, StringComparer.Ordinal)
                .Select(person => new TownConductAcquisition(WorldRuntime.CivicSharedRules.ConductSeenId(nativeActId, person.AgentId),
                    nativeActId, person.AgentId, "firsthand", world.WorldTick, person.Position,
                    DescribeNonLandConduct(record), ObserverHouseholdId: world.HouseholdFor(person.AgentId),
                    PrivateSiteHouseholdId: NonLandPrivateSite(world, position)?.HouseholdId)).ToArray();
            SetTown(world, town with
            {
                NonLandHearings = PruneNonLandConduct(town, town.NonLandHearings with
                {
                    ConductRecords = town.NonLandHearings.ConductRecords.Append(record).ToArray(),
                    Acquisitions = town.NonLandHearings.Acquisitions.Concat(observations).ToArray(),
                })
            });
        }
    }

    internal static TownNonLandHearingState PruneNonLandConduct(TownRuntimeState town, TownNonLandHearingState state)
    {
        var retained = state.Cases.Select(file => file.Allegation.IncidentId)
            .Concat((town.Council?.Proposals ?? []).Where(proposal => proposal.NonLandRequest is not null)
                .Select(proposal => proposal.NonLandRequest!.Allegation.IncidentId)).ToHashSet(StringComparer.Ordinal);
        foreach (var record in state.ConductRecords.Where(record => !retained.Contains(record.Id))
                     .OrderByDescending(record => record.Tick).ThenByDescending(record => record.Id, StringComparer.Ordinal)
                     .Take(UnfiledConductLimit)) retained.Add(record.Id);
        return state with
        {
            ConductRecords = state.ConductRecords.Where(record => retained.Contains(record.Id)).ToArray(),
            Acquisitions = state.Acquisitions.Where(item => retained.Contains(item.ConductId)).ToArray(),
        };
    }

    internal static bool HasPriorLawNotice(TownRuntimeState town, TownViolationAllegation allegation, string subject) =>
        town.NonLandHearings.ConductRecords.Any(record => record.Id == allegation.IncidentId && record.ActorId == subject &&
            record.Tick == allegation.ConductTick && record.Laws.Any(law => law.LawId == allegation.LawId &&
                law.Version == allegation.LawVersion && law.PriorNoticeIds.Count > 0));
    internal static bool KnowsConductLaw(TownRuntimeState town, string actor, TownConductLawSnapshot snapshot)
    {
        var version = town.Government?.Laws.FirstOrDefault(law => law.Id == snapshot.LawId)?.Versions
            .FirstOrDefault(item => item.Version == snapshot.Version);
        return version is not null && (town.Council?.Knowledge ?? []).Any(receipt => receipt.AgentId == actor &&
            town.Council!.Notices.Any(notice => notice.Id == receipt.NoticeId && notice.Kind == "law" &&
                notice.SubjectId == snapshot.LawId && notice.PostedTick >= version.AdoptedTick &&
                (version.EndedTick is null || notice.PostedTick < version.EndedTick)));
    }

    internal static bool CanObserveNonLandAct(ITownWorld world, string observer, string actor, GridPoint position)
    {
        if (!world.Agents.TryGetValue(observer, out var person) ||
            !world.IsWithinInteractionRange(person.Position, position, WorldRuntime.CivicSharedRules.ResourceInteractionRange)) return false;
        // Being beside a private worksite does not grant access to its contents or work inside it.
        var privateSite = NonLandPrivateSite(world, position);
        return privateSite is null || world.HouseholdFor(observer) == privateSite.HouseholdId || observer == actor;
    }

    internal static PlacedBuilding? NonLandPrivateSite(ITownWorld world, GridPoint position) => world.WorldSimulation.Buildings.FirstOrDefault(building =>
        building.HouseholdId is not null && world.WorldContent.Buildings.FirstOrDefault(item => item.CanonicalId == building.DefinitionId) is { } definition &&
        WorldContentSimulationRules.Footprint(definition, building).Contains(position));
    internal static string DescribeNonLandConduct(TownConductRecord record) =>
        $"Observed {record.ConductKind.Replace('_', ' ')} at ({record.Position.X},{record.Position.Y})" +
        (record.ItemKind is null ? "." : $", involving {record.Quantity} {record.ItemKind.Replace('_', ' ')}.");
    internal static (TownViolationAllegation Allegation, TownCaseEvidence Evidence)[] NonLandKnownReports(ITownWorld world, TownRuntimeState town, string actor)
    {
        var result = new List<(TownViolationAllegation, TownCaseEvidence)>();
        foreach (var acquisition in town.NonLandHearings.Acquisitions.Where(item => item.AgentId == actor)
                     .OrderBy(item => item.Id, StringComparer.Ordinal))
        {
            var record = town.NonLandHearings.ConductRecords.Single(item => item.Id == acquisition.ConductId);
            foreach (var law in record.Laws.Where(law => KnowsConductLaw(town, actor, law) ||
                         acquisition.Kind == "record_inspection" && town.NonLandHearings.Cases.Any(file => file.Id == acquisition.PublicCaseId &&
                             file.Allegation.LawId == law.LawId && file.Allegation.LawVersion == law.Version)))
                result.Add((new(record.Id, record.ActorId, record.ConductKind, record.Position, record.Tick,
                    law.LawId, law.Version, acquisition.Text, [acquisition.Id]),
                    NonLandEvidence(world, record, acquisition, actor, 1)));
        }
        return result.GroupBy(item => (item.Item1.IncidentId, item.Item1.LawId, item.Item1.LawVersion))
            .Select(group => group.OrderBy(item => item.Item2.Kind == "observation" ? 0 : item.Item2.Kind == "record" ? 1 : 2)
                .ThenBy(item => item.Item2.Id, StringComparer.Ordinal).First()).ToArray();
    }

    internal static TownCaseEvidence[] NonLandKnownEvidence(ITownWorld world, TownRuntimeState town,
        TownNonLandCase file, string actor) => town.NonLandHearings.Acquisitions
        .Where(item => item.AgentId == actor && item.ConductId == file.Allegation.IncidentId)
        .OrderBy(item => item.Id, StringComparer.Ordinal)
        .Select(item => NonLandEvidence(world, town.NonLandHearings.ConductRecords.Single(record => record.Id == item.ConductId),
            item, actor, file.Revisions[^1].Number))
        .Concat(NonLandKnownPublicRecords(town, world.HouseholdLandUseRights, world.TownLandTitles, actor,
            file.Allegation.Position, file.Revisions[^1].Number, world.WorldTick)).ToArray();
    internal static TownCaseEvidence NonLandEvidence(ITownWorld world, TownConductRecord record, TownConductAcquisition acquired,
        string actor, int revision) => new(acquired.Id, revision,
        acquired.Kind == "firsthand" ? "observation" : acquired.Kind == "record_inspection" ? "record" : "allegation",
        acquired.Kind, acquired.SourceAgentId ?? actor,
        record.Id, record.Version, acquired.Tick, actor, world.WorldTick, acquired.Text);
    internal static TownNonLandHearingState AcquireNonLandInspectedSources(ITownWorld world, TownRuntimeState town, TownNonLandCase file, string actor)
    {
        if (!world.Agents.TryGetValue(actor, out var reader) || !TownNonLandRules.ReadCurrent(file, actor, world.WorldTick))
            return town.NonLandHearings;
        var state = town.NonLandHearings;
        foreach (var evidence in file.Evidence.Where(item => item.Kind is "observation" or "record" &&
                     item.SourceRecordId == file.Allegation.IncidentId && item.SubmittedTick <= world.WorldTick))
        {
            var original = state.Acquisitions.FirstOrDefault(item => item.Id == evidence.Id);
            if (original is null || state.Acquisitions.Any(item => item.AgentId == actor && item.ConductId == original.ConductId &&
                    item.Kind == "record_inspection" && item.PublicCaseId == file.Id)) continue;
            var acquired = new TownConductAcquisition(WorldRuntime.CivicSharedRules.ConductInspectionId(original.ConductId, file.Id, actor),
                original.ConductId, actor, "record_inspection", world.WorldTick, reader.Position, evidence.Text,
                actor, original.Id, ObserverHouseholdId: world.HouseholdFor(actor), PublicCaseId: file.Id);
            state = state with { Acquisitions = state.Acquisitions.Append(acquired).ToArray() };
        }
        return state;
    }

    internal bool RelayNonLandKnownReport(ITownWorld world, TownRuntimeState town, string source, string recipient,
        string incidentId, string statement, TownConductAcquisition? selectedSource = null)
    {
        if (!world.Agents.TryGetValue(source, out var speaker) || !world.Agents.TryGetValue(recipient, out var listener) ||
            source == recipient || !world.IsWithinInteractionRange(speaker.Position, listener.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange) ||
            string.IsNullOrWhiteSpace(statement) || statement.Length > TownCouncilRules.MaximumProposalText || statement.Any(char.IsControl)) return false;
        town = world.Towns.Single(item => item.Id == town.Id);
        if (town.NonLandHearings.Acquisitions.Any(item => item.AgentId == recipient && item.ConductId == incidentId)) return true;
        var original = selectedSource ?? town.NonLandHearings.Acquisitions.Where(item => item.AgentId == source && item.ConductId == incidentId)
            .OrderBy(item => item.Tick).ThenBy(item => item.Id, StringComparer.Ordinal).FirstOrDefault();
        if (original is null) return false;
        var id = WorldRuntime.CivicSharedRules.ConductRelayId(incidentId, world.WorldTick, source, recipient);
        if (town.NonLandHearings.Acquisitions.Any(item => item.Id == id)) return true;
        var acquired = new TownConductAcquisition(id, incidentId, recipient, "relay", world.WorldTick,
            listener.Position, statement.Trim(), source, original.Id, speaker.Position, world.HouseholdFor(recipient));
        SetTown(world, town with { NonLandHearings = town.NonLandHearings with { Acquisitions = town.NonLandHearings.Acquisitions.Append(acquired).ToArray() } });
        return true;
    }

    internal bool NonLandRemedyTermKnownTo(ITownWorld world, TownRuntimeState town, TownRemedyTerm term, string actor)
    {
        if (term.TargetId is null) return true;
        if (term.Kind == "public_service_goods") return world.WorldSimulation.Buildings.Any(building =>
            building.InstanceId == term.TargetId && building.TownId == town.Id &&
            (TownForResident(world, actor) == town.Id || world.Agents.TryGetValue(actor, out var person) && world.IsWithinInteractionRange(person.Position, building.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange)));
        var lot = world.Society.Inventory.Lots.FirstOrDefault(item => item.Id == term.TargetId);
        if (lot is null) return false;
        if (lot.OwnerId == actor || lot.OwnerId == world.HouseholdFor(actor)) return true;
        return world.Agents.TryGetValue(actor, out var observer) && world.Agents.TryGetValue(term.ContributorId, out var contributor) && world.IsWithinInteractionRange(observer.Position, contributor.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange) &&
            ToolProgressionRules.IsTopLevelCarriedLot(lot, term.ContributorId) &&
            CanObserveNonLandAct(world, actor, term.ContributorId, contributor.Position);
    }

    internal static bool NonLandWorkAllowed(ITownWorld world, string actor) => world.IsAdult(actor) && world.Agents.TryGetValue(actor, out var person) &&
        !WorldRuntime.CivicSharedRules.NeedsUrgentFood(person) && !world.NeedsUrgentWarmth(person) && !world.IllDependentsNeedingCare(actor).Any() &&
        !world.ChildrenNeedingCare(actor).Any() &&
        IllnessRules.AllowsWork(actor, world.WorldTick, person.Survival?.IllnessBasisPoints ?? 0);
    internal static bool NonLandEquipmentRepairPaused(ITownWorld world, string actor) => world.Agents[actor].Equipment?.Repair is { } repair && world.Towns.Any(town => town.NonLandHearings.Agreements.Any(agreement => agreement.Status is "pending" or "overdue" &&
            !TownRemedyRules.IsSuperseded(town.NonLandHearings, agreement.Id) && agreement.Terms.Any(term =>
                term.Kind == "repair_equipment" && term.ContributorId == actor && term.TargetId == repair.LotId &&
                NonLandRemaining(town.NonLandHearings, agreement, term) > 0))) &&
        (world.IllDependentsNeedingCare(actor).Any() || world.ChildrenNeedingCare(actor).Any());
    internal static InventoryLot? NonLandReturnLot(ITownWorld world, TownRemedyTerm term, string? selectedId = null) => world.Society.Inventory.Lots
        .Where(lot => (selectedId is null || lot.Id == selectedId) && lot.OwnerId == term.ContributorId && ToolProgressionRules.IsTopLevelCarriedLot(lot, term.ContributorId) &&
            lot.DeliveryBuildingId is null && lot.ItemKind == term.ItemKind && (term.TargetId is null || lot.Id == term.TargetId) &&
            !InventoryContainerRules.IsContainer(lot.ItemKind) &&
            !PersonalEquipmentRules.IsSelected(world.Agents[term.ContributorId].Equipment, lot.Id) &&
            InventoryRules.CanReserve(InventoryIndex.For(world.Society.Inventory), lot, term.ContributorId, term.Quantity,
                InventoryHoldRules.BorrowedBy(term.ContributorId)))
        .OrderBy(lot => lot.Id, StringComparer.Ordinal).FirstOrDefault();
    internal static bool NonLandReturnIsCurrent(ITownWorld world, TownRemedyTerm term, string? selectedId = null) =>
        term.BeneficiaryId is { } recipient && recipient != term.ContributorId && world.Agents.TryGetValue(recipient, out var beneficiary) &&
        world.IsWithinInteractionRange(world.Agents[term.ContributorId].Position, beneficiary.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange) &&
        CanObserveNonLandAct(world, term.ContributorId, recipient, beneficiary.Position) && NonLandReturnLot(world, term, selectedId) is { } lot &&
        (!WorldRuntime.CivicSharedRules.IsEdibleFood(lot.ItemKind) || world.Agents[term.ContributorId].FullnessBasisPoints >= NeedThresholds.NonLandReturnFoodFullness &&
            world.PreferredFood(term.ContributorId, term.ContributorId).Sum(world.AvailableLotQuantity) - term.Quantity >= 2) && world.FreeCarryCapacity(recipient) >= term.Quantity;

    internal static bool NonLandRemedyFeasible(ITownWorld world, TownRuntimeState town, TownRemedyTerm term)
    {
        if (term.Quantity <= 0 || !NonLandWorkAllowed(world, term.ContributorId)) return false;
        var actor = term.ContributorId;
        var person = world.Agents[actor];
        if (term.Kind == "return_goods") return NonLandReturnIsCurrent(world, term);
        if (term.Kind == "public_service_goods")
        {
            var warehouse = world.WarehouseForResident(actor);
            return term.BeneficiaryId == town.Id && warehouse is not null && warehouse.TownId == town.Id &&
                (term.TargetId is null || term.TargetId == warehouse.InstanceId) && WorldRuntime.CivicSharedRules.WarehouseResourceKinds.Contains(term.ItemKind ?? "") && world.DestinationRoom(warehouse.InstanceId) >= term.Quantity && world.PersonalWarehouseAvailableQuantity(actor, term.ItemKind!) - WorldRuntime.CivicSharedRules.WarehouseLoadQuantity >= term.Quantity &&
                (person.Position == warehouse.Position || world.ReachNonLandService(actor, warehouse.Position).Count > 0);
        }
        if (term.Kind != "repair_equipment" || term.Quantity != 1 || term.TargetId is null) return false;
        var predecessor = town.NonLandHearings.Offers.Where(offer => offer.Terms.Any(item => item.Id == term.Id))
            .Select(offer => offer.ReplacesOfferId is { } previous ? town.NonLandHearings.Offers.FirstOrDefault(item => item.Id == previous)?.AgreementId : null)
            .FirstOrDefault(id => id is not null);
        if (world.Towns.Select(other => other.Id == town.Id ? town : other).Any(other => other.NonLandHearings.Agreements.Any(agreement =>
                agreement.Status is "pending" or "overdue" && !TownRemedyRules.IsSuperseded(other.NonLandHearings, agreement.Id) &&
                !(other.Id == town.Id && agreement.Id == predecessor) && agreement.Terms.Any(existing =>
                    existing.Kind == "repair_equipment" && existing.ContributorId == term.ContributorId && existing.TargetId == term.TargetId &&
                    NonLandRemaining(other.NonLandHearings, agreement, existing) > 0 &&
                    (other.Id != town.Id || existing.Id != term.Id))))) return false;
        var target = world.Society.Inventory.Lots.FirstOrDefault(lot => lot.Id == term.TargetId && lot.ItemKind == term.ItemKind &&
            lot.ConditionBasisPoints < 10_000 && (lot.OwnerId == actor || lot.OwnerId == world.HouseholdFor(actor)));
        if (target is null || term.BeneficiaryId != target.OwnerId) return false;
        if (person.Equipment?.Repair?.LotId == target.Id && world.CanContinueEquipmentRepair(actor)) return true;
        if (!NonLandRepairMaterials(target.ItemKind).All(input => world.HasCarriedMaterial(actor, input.ResourceId, input.Amount))) return false;
        var native = new List<CognitionCandidate>();
        world.AddToolRepairCandidates(native, actor);
        world.AddEquipmentCandidates(native, actor, person);
        world.AddHandcartCandidates(native, actor, person);
        return native.Any(candidate => candidate.Id == WorldRuntime.CivicSharedRules.RepairToolPrefix + target.Id || candidate.Id == WorldRuntime.CivicSharedRules.RepairCartPrefix + target.Id ||
            candidate.Id == "repair_equipment" && world.WornEquipmentItems(actor).Any(lot => lot.Id == target.Id) && world.CanPrepareEquipmentRepair(actor, person, target));
    }

    internal static bool NonLandRemedyDurationFeasible(ITownWorld world, TownRuntimeState town, TownRemedyTerm[] terms, long ticks)
    {
        if (ticks <= 0 || terms.Length == 0 || terms.Any(term => !NonLandRemedyFeasible(world, town, term)) ||
            !NonLandRemedyCapacityFeasible(world, terms)) return false;
        foreach (var group in terms.GroupBy(term => term.ContributorId, StringComparer.Ordinal))
        {
            var actor = group.Key;
            var person = world.Agents[actor];
            var position = person.Position;
            long needed = 0;
            var used = new Dictionary<string, long>(StringComparer.Ordinal);
            var namedReturns = new Dictionary<string, long>(StringComparer.Ordinal);
            var repaired = new HashSet<string>(StringComparer.Ordinal);
            foreach (var term in group)
            {
                GridPoint destination;
                long work;
                if (term.Kind == "repair_equipment")
                {
                    if (!repaired.Add(term.TargetId!)) return false;
                    var target = world.Society.Inventory.GetLot(term.TargetId!);
                    var inProgress = person.Equipment?.Repair?.LotId == target.Id ? person.Equipment.Repair : null;
                    var materials = inProgress is null ? NonLandRepairMaterials(target.ItemKind) : [];
                    foreach (var input in materials)
                        used[input.ResourceId] = used.GetValueOrDefault(input.ResourceId) + input.Amount;
                    if (target.ItemKind == InventoryContainerRules.Handcart)
                    {
                        destination = new(target.GroundPosition!.Value.X, target.GroundPosition.Value.Y);
                        work = 1;
                    }
                    else if (ToolProgressionRules.Find(target.ItemKind) is not null)
                    {
                        destination = world.HouseholdBuildingWithTag(world.HouseholdFor(actor), "blacksmith")!.Position;
                        work = 1;
                    }
                    else
                    {
                        destination = world.EquipmentRepairSite(actor, target)!.Position;
                        var repairTicks = world.SkilledWorkTicks(actor, SkillKind.Crafting, PersonalEquipmentRules.RepairWorkTicks);
                        work = inProgress is null ? 1 + repairTicks : Math.Max(1, repairTicks - inProgress.WorkDone);
                    }
                }
                else
                {
                    used[term.ItemKind!] = used.GetValueOrDefault(term.ItemKind!) + term.Quantity;
                    if (term.Kind == "return_goods" && term.TargetId is { } source)
                        namedReturns[source] = namedReturns.GetValueOrDefault(source) + term.Quantity;
                    destination = term.Kind == "return_goods" ? world.Agents[term.BeneficiaryId!].Position : world.WarehouseForResident(actor)!.Position;
                    work = term.Kind == "return_goods" ? 1 : ((long)term.Quantity + WorldRuntime.CivicSharedRules.WarehouseLoadQuantity - 1) / WorldRuntime.CivicSharedRules.WarehouseLoadQuantity;
                }
                var range = term.Kind == "return_goods" ? WorldRuntime.CivicSharedRules.ResourceInteractionRange : 0;
                if (!world.IsWithinInteractionRange(position, destination, range))
                {
                    if (position == person.Position) needed += person.TravelCooldownTicks;
                    var route = world.ReachLeg(actor, position, destination, ReachPurpose.NonLandService, range, 0, SwimmingPolicy.WhenCapable);
                    if (route.Count < 2) return false;
                    for (var step = 1; step < route.Count; step++)
                    {
                        // The last arrival needs one tick; its cooldown delays later travel, not onsite work.
                        needed += step == route.Count - 1 ? 1 : (world.TravelStepCost(actor, route[step - 1], route[step]) + 99) / 100 +
                            IllnessRules.TravelDelayTicks(person.Survival?.IllnessBasisPoints ?? 0);
                    }
                    position = route[^1];
                }
                needed += work;
                if (needed > ticks) return false;
            }
            foreach (var promise in namedReturns)
                if (world.AvailableLotQuantity(world.Society.Inventory.GetLot(promise.Key)) < promise.Value) return false;
            foreach (var expenditure in used)
            {
                var stock = world.Society.Inventory.Lots.Where(lot => lot.OwnerId == actor &&
                    ToolProgressionRules.IsTopLevelCarriedLot(lot, actor) && lot.DeliveryBuildingId is null &&
                    lot.ItemKind == expenditure.Key).Sum(lot => (long)world.AvailableLotQuantity(lot));
                var reserve = group.Any(term => term.Kind == "public_service_goods" && term.ItemKind == expenditure.Key)
                    ? WorldRuntime.CivicSharedRules.WarehouseLoadQuantity : WorldRuntime.CivicSharedRules.IsEdibleFood(expenditure.Key) ? 2 : 0;
                if (stock - reserve < expenditure.Value) return false;
            }
        }
        return true;
    }

    internal static bool NonLandRemedyCapacityFeasible(ITownWorld world, IEnumerable<TownRemedyTerm> terms)
    {
        foreach (var returns in terms.Where(term => term.Kind == "return_goods")
                     .GroupBy(term => term.BeneficiaryId!, StringComparer.Ordinal))
            if (!world.Agents.ContainsKey(returns.Key) || returns.Sum(term => (long)term.Quantity) > world.FreeCarryCapacity(returns.Key)) return false;
        var deliveries = terms.Where(term => term.Kind == "public_service_goods")
            .Select(term => (Term: term, Warehouse: world.WarehouseForResident(term.ContributorId))).ToArray();
        if (deliveries.Any(delivery => delivery.Warehouse is null)) return false;
        foreach (var storage in deliveries.GroupBy(delivery => delivery.Warehouse!.InstanceId, StringComparer.Ordinal))
            if (storage.Sum(delivery => (long)delivery.Term.Quantity) > world.DestinationRoom(storage.Key)) return false;
        return true;
    }

    internal static string NonLandRemedyCandidateId(TownRuntimeState town, TownRestorativeAgreement agreement, TownRemedyTerm term) =>
        WorldRuntime.CivicSharedRules.NonLandRemedyChoiceId(town.Id, agreement.Id, term.Id);
    internal static int NonLandRemaining(TownNonLandHearingState state, TownRestorativeAgreement agreement, TownRemedyTerm term) =>
        term.Quantity - state.Effects.Where(effect => effect.AgreementId == agreement.Id && effect.TermId == term.Id).Sum(effect => effect.Quantity);
    internal static void AddNonLandRemedyCandidates(ITownWorld world, List<CognitionCandidate> candidates, string actor, TownRuntimeState town)
    {
        if (world.Agents.TryGetValue(actor, out var speaker))
            foreach (var record in town.NonLandHearings.ConductRecords.Where(record =>
                         town.NonLandHearings.Acquisitions.Any(item => item.ConductId == record.Id && item.AgentId == actor)))
                foreach (var listener in world.Agents.Values.Where(person => person.AgentId != actor && world.IsWithinInteractionRange(speaker.Position, person.Position, WorldRuntime.CivicSharedRules.ResourceInteractionRange) &&
                             !town.NonLandHearings.Acquisitions.Any(item => item.ConductId == record.Id && item.AgentId == person.AgentId)))
                    if (PlanNonLandReportRelay(world, actor, town, record, listener.AgentId) is { } relay && CheckNonLandReportRelay(world, relay).Allowed)
                        candidates.Add(new(relay.CandidateId, "Tell this nearby person what you observed or were told about this act; it remains a report.", 185, listener.AgentId)
                        { ActionPlan = relay });
        if (!NonLandWorkAllowed(world, actor)) return;
        foreach (var agreement in town.NonLandHearings.Agreements.Where(item => item.Status is "pending" or "overdue" &&
                     !TownRemedyRules.IsSuperseded(town.NonLandHearings, item.Id))
                     .OrderBy(item => item.Id, StringComparer.Ordinal))
            foreach (var term in agreement.Terms.Where(item => item.ContributorId == actor))
            {
                if (PlanNonLandWork(world, actor, town, agreement, term) is { } plan && CheckNonLandWork(world, plan).Allowed)
                    candidates.Add(new(plan.CandidateId, $"Voluntarily complete agreed {term.Kind.Replace('_', ' ')} using real goods or repair work.", 185, term.TargetId)
                    { ActionPlan = plan });
            }
    }

    internal static bool TryPlanNonLandPhysical(ITownWorld world, TownRuntimeState town, string actor, string candidateId,
        ActionPlan? originalPlan, out ActionPlan? selected)
    {
        selected = originalPlan switch
        {
            NonLandWorkActionPlan work when work.Choice.TownId == town.Id && work.CandidateId == candidateId => work,
            NonLandReportRelayActionPlan relay when relay.Choice.TownId == town.Id && relay.CandidateId == candidateId => relay,
            _ => null,
        };
        if (selected is not null) return true;
        if (candidateId.StartsWith(NonLandRelayPrefix, StringComparison.Ordinal))
        {
            foreach (var record in town.NonLandHearings.ConductRecords)
                foreach (var listener in world.Agents.Keys)
                    if (candidateId == NonLandRelayCandidateId(town, record, listener))
                    {
                        selected = originalPlan as NonLandReportRelayActionPlan ?? PlanNonLandReportRelay(world, actor, town, record, listener);
                        return true;
                    }
            return false;
        }
        if (!candidateId.StartsWith(NonLandRemedyPrefix, StringComparison.Ordinal)) return false;
        town = world.Towns.Single(item => item.Id == town.Id);
        foreach (var agreement in town.NonLandHearings.Agreements.Where(item => item.Status is "pending" or "overdue" &&
                     !TownRemedyRules.IsSuperseded(town.NonLandHearings, item.Id)))
            foreach (var term in agreement.Terms.Where(item => item.ContributorId == actor))
                if (candidateId == NonLandRemedyCandidateId(town, agreement, term))
                {
                    selected = originalPlan as NonLandWorkActionPlan ?? PlanNonLandWork(world, actor, town, agreement, term);
                    return true;
                }
        return false;
    }

    internal bool ApplyNonLandRemedyAction(ITownWorld world, TownRuntimeState town, string actor, string candidateId, ActionPlan? originalPlan = null)
    {
        if (!TryPlanNonLandPhysical(world, town, actor, candidateId, originalPlan, out var selected)) return false;
        if (selected is NonLandReportRelayActionPlan relay)
        {
            if (CheckNonLandReportRelay(world, relay).Refusal is { } refusal) { world.RefuseChoice(relay, refusal); return true; }
            ApplyCheckedNonLandReportRelay(world, relay);
        }
        else if (selected is NonLandWorkActionPlan plan)
        {
            if (CheckNonLandWork(world, plan).Refusal is { } refusal) { world.RefuseChoice(plan, refusal); return true; }
            ApplyCheckedNonLandWork(world, plan);
        }
        return true;
    }

    internal void ApplyCheckedNonLandReportRelay(ITownWorld world, NonLandReportRelayActionPlan plan) =>
        RelayNonLandKnownReport(world, world.Towns.Single(town => town.Id == plan.Choice.TownId), plan.Actor,
            plan.Choice.Recipient, plan.Conduct.Id, plan.Statement, plan.Source);

    internal void ApplyCheckedNonLandWork(ITownWorld world, NonLandWorkActionPlan plan)
    {
        var actor = plan.Actor;
        var term = plan.Term;
        var remaining = plan.Remaining;
        var previousSelection = world.NonLandRemedySelection;
        world.NonLandRemedySelection = (plan.Choice.TownId, plan.Agreement.Id, term.Id);
        try
        {
            if (term.Kind == "return_goods")
            {
                var lot = NonLandReturnLot(world, term with { Quantity = remaining }, plan.StockId)!;
                var operation = WorldRuntime.CivicSharedRules.NativeReturnId(world.WorldTick, actor, world.NextEventId);
                world.RunInventoryCommand(InventorySystem.ApplyCheckedNonLandWork(operation, actor, term, lot, remaining));
                RecordNonLandGoodsCompletion(world, actor, lot, term.BeneficiaryId!, remaining, null, operation, "return_goods");
                world.AppendEvent(new VoluntaryGoodsReturnedEventPayload(actor, term.BeneficiaryId, lot.Id, remaining));
            }
            else if (term.Kind == "public_service_goods")
                DeliverNonLandTownGoods(world, actor, term, remaining, plan);
            else
            {
                if (plan.Phase == NonLandWorkPhase.ContinueRepair) world.ContinueEquipmentRepair(actor);
                else world.ApplyNonLandRepair(plan.Repair!);
            }
        }
        finally
        {
            world.NonLandRemedySelection = previousSelection;
        }
    }

    internal static string NonLandRelayCandidateId(TownRuntimeState town, TownConductRecord record, string listener) =>
        WorldRuntime.CivicSharedRules.NonLandRelayChoiceId(town.Id, record.Id, listener);
    internal void DeliverNonLandTownGoods(ITownWorld world, string actor, TownRemedyTerm term, int remaining, NonLandWorkActionPlan? plan = null)
    {
        var warehouse = plan is null ? world.WarehouseForResident(actor)! : world.WorldSimulation.Buildings.Single(building => building.InstanceId == plan.WarehouseId);
        if (world.Agents[actor].Position != warehouse.Position)
        {
            world.MoveToward(actor, world.Agents[actor], warehouse.Position, "voluntary_town_service", 0);
            return;
        }
        if (world.PersonalWarehouseSurplus(actor, term.ItemKind, plan?.StockId) is not { } surplus) return;
        var lot = surplus.Lot;
        var quantity = plan?.Quantity ?? Math.Min(remaining, Math.Min(WorldRuntime.CivicSharedRules.WarehouseLoadQuantity,
            Math.Min(world.DestinationRoom(warehouse.InstanceId), surplus.Quantity)));
        if (quantity <= 0) return;
        var availableBefore = world.PersonalWarehouseAvailableQuantity(actor, lot.ItemKind);
        var operation = WorldRuntime.CivicSharedRules.WarehouseStockId(world.WorldTick, actor);
        world.RunInventoryCommand(InventorySystem.DeliverNonLandTownGoods(operation, actor, warehouse, lot, quantity));
        RecordNonLandGoodsCompletion(world, actor, lot, warehouse.TownId!, quantity, warehouse.InstanceId, operation, "public_service_goods", availableBefore);
        world.AppendEvent(new TownResourcesStoredEventPayload(actor, lot.Id, quantity, warehouse.InstanceId));
    }

    internal void RecordNonLandRepairCompletion(ITownWorld world, string actor, InventoryLot originalTarget, string repairedLotId,
        string nativeReceiptId, GridPoint position, IReadOnlyList<Identity> reservationIds)
    {
        var result = world.Society.Inventory.GetLot(repairedLotId);
        if (result.ConditionBasisPoints <= originalTarget.ConditionBasisPoints) return;
        nativeReceiptId = DerivedId.Create(nativeReceiptId);
        var receipt = new TownNativeRemedyReceipt(Identity.Parse(nativeReceiptId), "repair_equipment", actor, world.WorldTick,
            originalTarget.OwnerId, originalTarget.ItemKind, 1, originalTarget.Id, originalTarget.Id,
            repairedLotId, originalTarget.OwnerId, result.OwnerId, position,
            originalTarget.ConditionBasisPoints, result.ConditionBasisPoints, "", world.HouseholdFor(actor), TownForResident(world, actor),
            originalTarget.Quantity, 1, NonLandRepairMaterials(originalTarget.ItemKind).Zip(reservationIds,
                (input, id) => new TownNativeRepairInput(input.ResourceId, world.Society.Inventory.GetReservation(id))).ToArray());
        RecordNonLandNativeReceipt(world, receipt);
        RecordNonLandConduct(world, actor, "repair_equipment", position, originalTarget.Id, originalTarget.ItemKind, 1, nativeReceiptId);
    }

    internal void RecordNonLandGoodsCompletion(ITownWorld world, string actor, InventoryLot sourceLot, string recipientId,
        int quantity, string? storageBuildingId, string nativeReceiptId, string kind, long? carriedAvailableBefore = null)
    {
        var resultId = quantity == sourceLot.Quantity ? sourceLot.Id : DerivedId.Create(sourceLot.Id + "#transfer:" + nativeReceiptId);
        var result = world.Society.Inventory.GetLot(resultId);
        var receipt = new TownNativeRemedyReceipt(Identity.Parse(nativeReceiptId), kind, actor, world.WorldTick, recipientId,
            sourceLot.ItemKind, quantity, storageBuildingId ?? sourceLot.Id, sourceLot.Id, resultId,
            sourceLot.OwnerId, result.OwnerId, world.Agents[actor].Position,
            sourceLot.ConditionBasisPoints, result.ConditionBasisPoints, "", world.HouseholdFor(actor), TownForResident(world, actor),
            sourceLot.Quantity, world.AvailableLotQuantity(sourceLot), [], carriedAvailableBefore);
        RecordNonLandNativeReceipt(world, receipt);
        RecordNonLandConduct(world, actor, kind, receipt.Position, receipt.TargetId, receipt.ItemKind, quantity, nativeReceiptId);
    }

    internal void RecordNonLandNativeReceipt(ITownWorld world, TownNativeRemedyReceipt receipt)
    {
        if (world.Towns.Any(town => town.NonLandHearings.NativeReceipts.Any(item => item.Id == receipt.Id))) return;
        // One physical completion cannot be spent against two agreements or two Towns.
        foreach (var town in world.Towns.OrderBy(item => item.Id, StringComparer.Ordinal).ToArray())
            foreach (var agreement in town.NonLandHearings.Agreements.Where(item => item.Status is "pending" or "overdue" &&
                     !TownRemedyRules.IsSuperseded(town.NonLandHearings, item.Id))
                         .OrderBy(item => item.AcceptedTick).ThenBy(item => item.Id, StringComparer.Ordinal))
                foreach (var term in agreement.Terms)
                {
                    if (world.NonLandRemedySelection is { } selected &&
                        (selected.TownId != town.Id || selected.AgreementId != agreement.Id || selected.TermId != term.Id)) continue;
                    if (agreement.AcceptedTick > receipt.Tick || term.Kind != receipt.Kind || term.ContributorId != receipt.ActorId ||
                        term.BeneficiaryId != receipt.BeneficiaryId || term.ItemKind != receipt.ItemKind ||
                        term.TargetId is not null && term.TargetId != receipt.TargetId) continue;
                    var remaining = NonLandRemaining(town.NonLandHearings, agreement, term);
                    if (remaining <= 0) continue;
                    receipt = receipt with { Version = NonLandDigest(receipt) };
                    var effect = new TownRemedyEffect(WorldRuntime.CivicSharedRules.RemedyEffectId(receipt.Id), agreement.Id, term.Id, receipt.ActorId,
                        receipt.Tick, receipt.Kind, receipt.BeneficiaryId, receipt.ItemKind, Math.Min(remaining, receipt.Quantity),
                        term.TargetId, receipt.Id, receipt.Version);
                    var state = town.NonLandHearings with { NativeReceipts = town.NonLandHearings.NativeReceipts.Append(receipt).ToArray() };
                    SetTown(world, town with { NonLandHearings = TownRemedyRules.RecordEffect(state, effect) });
                    world.AppendEvent(new LawCaseRemedyEffectEventPayload(receipt.ActorId, town.Id, agreement.Id), receipt.Position);
                    return;
                }
    }

    internal static IReadOnlyList<ContentQuantity> NonLandRepairMaterials(string itemKind) =>
        itemKind == InventoryContainerRules.Handcart ? [new("wood", 1), new("iron_fittings", 1), new("rope", 1)] :
        ToolProgressionRules.Find(itemKind) is not null ? ToolProgressionRules.RepairMaterials(itemKind) :
        PersonalEquipmentRules.RepairMaterials(itemKind);
}

